// ❌ OLD: Direct HTTP REST calls between internal microservices
// introduce connection overhead, DNS lookups, and lack built-in message queuing.
import { Injectable } from '@nestjs/common';
import axios from 'axios';

@Injectable()
export class OrderService {
  async createOrder(orderData: any) {
    // Synchronous HTTP coupling:
    const res = await axios.post('http://billing-service:3001/charge', orderData);
    return res.data;
  }
}

import { Injectable, Inject } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { firstValueFrom } from 'rxjs';

@Injectable()
export class OrderService {
  constructor(@Inject('BILLING_SERVICE') private client: ClientProxy) {}

  async createOrder(orderData: any) {
    // ✅ NEW: RPC call via TCP/Redis/Kafka with automatic correlation IDs:
    const result$ = this.client.send({ cmd: 'charge' }, orderData);
    return await firstValueFrom(result$);
  }
}

